UPDATE news_channel
SET credential_status = #{target}
WHERE code = #{code}
  AND credential_status = #{expected}

UPDATE news_channel
SET credential_json        = #{credentialJson},
    credential_status      = #{credentialStatus},
    credential_account = #{credentialAccount},
    credential_update_time = #{credentialUpdateTime}
WHERE code = #{code}

UPDATE news_channel
SET enabled = #{enabled}
WHERE code = #{code}
